u8 TryRejectSpellActivationGate(u16 cardId)
{
  u8 i;

  for (i = 0; i < ARRAY_COUNT(sSpellActivationGates); i++) {
    if (sSpellActivationGates[i].cardId != cardId)
      continue;
    if (sSpellActivationGates[i].canActivate())
      return FALSE;
    if (sSpellActivationGates[i].playForbiddenSfx)
      PlayMusic(SFX_FORBIDDEN);
    gDuelCursor.state = 0;
    DisplayCardInfoBar();
    sub_8041E70(gDuelCursor.destY, gDuelCursor.currentY);
    return TRUE;
  }
  return FALSE;
}
